referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const out = [];
  for (const sub of d.subscriptions) {
    let count = 0;
    for (const event of d.source) {
      if (count >= sub.limit) break;
      if (event.op === "next") {
        out.push([sub.id, "next", event.value]);
        count++;
      } else {
        out.push(event.op === "error" ? [sub.id, "error", event.value] : [sub.id, "complete"]);
        break;
      }
    }
  }
  return out;
}

